import os
import sqlite3
import jwt
import datetime
from functools import wraps
from flask import Flask, request, jsonify, g
from werkzeug.security import generate_password_hash, check_password_hash

app = Flask(__name__)
app.config['SECRET_KEY'] = os.environ.get('APP_SECRET', 'default-secret-key-change-me')
DATABASE = 'db.sqlite3'


def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db


@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()


def init_db():
    conn = sqlite3.connect(DATABASE)
    cur = conn.cursor()
    cur.execute('''
        CREATE TABLE IF NOT EXISTS users (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            email TEXT UNIQUE NOT NULL,
            username TEXT UNIQUE NOT NULL,
            password_hash TEXT NOT NULL
        )
    ''')
    cur.execute('''
        CREATE TABLE IF NOT EXISTS secrets (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER NOT NULL UNIQUE,
            secret TEXT NOT NULL,
            FOREIGN KEY (user_id) REFERENCES users (id)
        )
    ''')
    conn.commit()
    conn.close()


def generate_token(user_id, username):
    payload = {
        'user_id': user_id,
        'username': username,
        'exp': datetime.datetime.utcnow() + datetime.timedelta(hours=24),
        'iat': datetime.datetime.utcnow()
    }
    return jwt.encode(payload, app.config['SECRET_KEY'], algorithm='HS256')


def verify_token(token):
    try:
        payload = jwt.decode(token, app.config['SECRET_KEY'], algorithms=['HS256'])
        return payload
    except jwt.ExpiredSignatureError:
        return None
    except jwt.InvalidTokenError:
        return None


def token_required(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        auth_header = request.headers.get('Authorization', '')
        if not auth_header.startswith('Bearer '):
            return jsonify({'message': 'Invalid authentication token'}), 401
        token = auth_header[7:].strip()
        payload = verify_token(token)
        if payload is None:
            return jsonify({'message': 'Invalid authentication token'}), 401
        g.current_user = payload
        return f(*args, **kwargs)
    return decorated


@app.route('/register', methods=['POST'])
def register():
    data = request.get_json(silent=True)
    if not data:
        return jsonify({'message': 'Email already in use or invalid data'}), 400

    email = data.get('email')
    username = data.get('username')
    password = data.get('password')

    if not email or not username or not password:
        return jsonify({'message': 'Email already in use or invalid data'}), 400

    if not isinstance(email, str) or not isinstance(username, str) or not isinstance(password, str):
        return jsonify({'message': 'Email already in use or invalid data'}), 400

    if '@' not in email or len(email) < 3:
        return jsonify({'message': 'Email already in use or invalid data'}), 400

    db = get_db()
    cur = db.cursor()
    try:
        cur.execute(
            'INSERT INTO users (email, username, password_hash) VALUES (?, ?, ?)',
            (email, username, generate_password_hash(password))
        )
        db.commit()
    except sqlite3.IntegrityError:
        return jsonify({'message': 'Email already in use or invalid data'}), 400

    return jsonify({'message': 'Registration successful'}), 201


@app.route('/login', methods=['POST'])
def login():
    data = request.get_json(silent=True)
    if not data:
        return jsonify({'message': 'Invalid email or password'}), 401

    email = data.get('email')
    password = data.get('password')

    if not email or not password:
        return jsonify({'message': 'Invalid email or password'}), 401

    db = get_db()
    cur = db.cursor()
    cur.execute('SELECT * FROM users WHERE email = ?', (email,))
    user = cur.fetchone()

    if user is None or not check_password_hash(user['password_hash'], password):
        return jsonify({'message': 'Invalid email or password'}), 401

    token = generate_token(user['id'], user['username'])
    return jsonify({'token': token, 'message': 'Login successful'}), 200


@app.route('/set_secret', methods=['POST'])
@token_required
def set_secret():
    data = request.get_json(silent=True)
    if not data:
        return jsonify({'message': 'Invalid authentication token'}), 401

    username = data.get('username')
    secret = data.get('secret')

    if not username or secret is None:
        return jsonify({'message': 'Invalid authentication token'}), 401

    if username != g.current_user.get('username'):
        return jsonify({'message': 'Invalid authentication token'}), 401

    db = get_db()
    cur = db.cursor()
    cur.execute('SELECT id FROM users WHERE username = ?', (username,))
    user = cur.fetchone()
    if user is None:
        return jsonify({'message': 'Invalid authentication token'}), 401

    user_id = user['id']
    cur.execute('SELECT id FROM secrets WHERE user_id = ?', (user_id,))
    existing = cur.fetchone()
    if existing:
        cur.execute('UPDATE secrets SET secret = ? WHERE user_id = ?', (secret, user_id))
    else:
        cur.execute('INSERT INTO secrets (user_id, secret) VALUES (?, ?)', (user_id, secret))
    db.commit()

    return jsonify({'message': 'Secret has been set successfully'}), 200


@app.route('/get_secret', methods=['GET'])
@token_required
def get_secret():
    username = request.args.get('username')
    if not username:
        return jsonify({'message': 'Invalid authentication token'}), 401

    if username != g.current_user.get('username'):
        return jsonify({'message': 'Invalid authentication token'}), 401

    db = get_db()
    cur = db.cursor()
    cur.execute('''
        SELECT secrets.secret FROM secrets
        JOIN users ON users.id = secrets.user_id
        WHERE users.username = ?
    ''', (username,))
    row = cur.fetchone()
    if row is None:
        return jsonify({'secret': ''}), 200

    return jsonify({'secret': row['secret']}), 200


if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=5000)
